import{_ as o}from"./chunks/thumb-01.DMo2YzKu.js";import{_ as r,H as e,f as a,i as s}from"./chunks/framework.Cvt1eIE0.js";const C=JSON.parse('{"title":"Cursor 使用教程：从安装到 Agent 与 Composer 实战","description":"","frontmatter":{"title":"Cursor 使用教程：从安装到 Agent 与 Composer 实战","date":"2026-05-22T00:00:00.000Z","category":"技术","tags":["AI","Cursor","教程"],"excerpt":"基于 VS Code 的 AI IDE：Tab 补全、Chat、Composer/Agent 多文件编辑与项目级上下文配置。"},"headers":[],"relativePath":"posts/技术/cursor-ai-coding-tutorial.md","filePath":"posts/技术/cursor-ai-coding-tutorial.md"}'),d={name:"posts/技术/cursor-ai-coding-tutorial.md"};function l(i,t,n,c,u,h){return e(),a("div",null,[...t[0]||(t[0]=[s('<img src="'+o+'" alt="配图" class="article-banner" loading="lazy"><h1 id="cursor-使用教程" tabindex="-1">Cursor 使用教程 <a class="header-anchor" href="#cursor-使用教程" aria-label="Permalink to &quot;Cursor 使用教程&quot;">​</a></h1><p><a href="https://cursor.com" target="_blank" rel="noreferrer">Cursor</a> 是在 VS Code 基础上深度集成 AI 的独立 IDE，适合「边写边问、多文件一起改」的日常开发。本文是本站原创入门笔记，侧重可复现的工作流。</p><h2 id="适合谁" tabindex="-1">适合谁 <a class="header-anchor" href="#适合谁" aria-label="Permalink to &quot;适合谁&quot;">​</a></h2><ul><li>已习惯 VS Code 快捷键与扩展生态</li><li>需要<strong>可视化 diff</strong>、多文件 Agent 编辑</li><li>希望在一个窗口里完成 Chat + 改代码 + 跑终端</li></ul><p>不太适合：只想在纯终端里跑 Agent、且不想换编辑器的人（可转向 Claude Code / Codex CLI）。</p><h2 id="安装与迁移" tabindex="-1">安装与迁移 <a class="header-anchor" href="#安装与迁移" aria-label="Permalink to &quot;安装与迁移&quot;">​</a></h2><ol><li>从官网下载 macOS / Windows / Linux 安装包。</li><li>首次启动可<strong>导入 VS Code 设置与扩展</strong>，降低迁移成本。</li><li>登录 Cursor 账号并选择订阅档（Free / Pro / Business，以官网为准）。</li></ol><h2 id="核心能力一览" tabindex="-1">核心能力一览 <a class="header-anchor" href="#核心能力一览" aria-label="Permalink to &quot;核心能力一览&quot;">​</a></h2><table tabindex="0"><thead><tr><th>能力</th><th>作用</th><th>典型快捷键/入口</th></tr></thead><tbody><tr><td><strong>Tab 补全</strong></td><td>行级/块级预测补全</td><td>输入时自动触发</td></tr><tr><td><strong>Chat</strong></td><td>单文件或选区问答</td><td>侧边栏 Chat</td></tr><tr><td><strong>Composer / Agent</strong></td><td>跨文件规划与修改</td><td><code>Cmd+I</code> / Composer 面板</td></tr><tr><td><strong>@ 上下文</strong></td><td>精确引用文件、文档、Git</td><td>输入 <code>@Files</code> <code>@Codebase</code> 等</td></tr></tbody></table><h2 id="推荐工作流" tabindex="-1">推荐工作流 <a class="header-anchor" href="#推荐工作流" aria-label="Permalink to &quot;推荐工作流&quot;">​</a></h2><h3 id="_1-小改-chat-选区" tabindex="-1">1. 小改：Chat + 选区 <a class="header-anchor" href="#_1-小改-chat-选区" aria-label="Permalink to &quot;1. 小改：Chat + 选区&quot;">​</a></h3><p>选中函数或报错栈 → Chat 里描述目标 → 应用补丁前<strong>逐段看 diff</strong>。</p><h3 id="_2-大改-composer-明确约束" tabindex="-1">2. 大改：Composer + 明确约束 <a class="header-anchor" href="#_2-大改-composer-明确约束" aria-label="Permalink to &quot;2. 大改：Composer + 明确约束&quot;">​</a></h3><p>在 Composer 里写清：</p><ul><li>要改的目录范围（如 <code>lib/features/auth/</code>）</li><li>必须通过的测试（<code>flutter test test/auth/</code>）</li><li>禁止动到的模块（如 <code>generated/</code>）</li></ul><h3 id="_3-项目规则-cursor-rules-或-rules" tabindex="-1">3. 项目规则：<code>.cursor/rules</code> 或 Rules <a class="header-anchor" href="#_3-项目规则-cursor-rules-或-rules" aria-label="Permalink to &quot;3. 项目规则：`.cursor/rules` 或 Rules&quot;">​</a></h3><p>把团队约定写进规则文件，例如：</p><ul><li>状态管理用 Riverpod，不用 setState 泥球</li><li>新 API 必须带 dartdoc</li><li>禁止提交 <code>print</code> 调试</li></ul><p>规则越具体，Agent 越少「自作主张」。</p><h2 id="上下文技巧" tabindex="-1">上下文技巧 <a class="header-anchor" href="#上下文技巧" aria-label="Permalink to &quot;上下文技巧&quot;">​</a></h2><ul><li><strong><code>@Codebase</code></strong>：适合「这段逻辑在哪被调用」类问题，注意大仓库会消耗额度。</li><li><strong><code>@Docs</code></strong>：可挂官方文档 URL，减少模型胡编 API。</li><li><strong><code>.cursorignore</code></strong>：排除 <code>build/</code>、<code>node_modules/</code>，提速并减少噪声。</li></ul><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><p><strong>Q：和 GitHub Copilot 能一起开吗？</strong><br> A：通常二选一，避免两套补全打架。以 Cursor 自带模型为主即可。</p><p><strong>Q：Agent 改坏了怎么办？</strong><br> A：用 Git 分支 + 小步提交；Composer 前先 <code>git checkout -b ai/cursor-task</code>。</p><p><strong>Q：公司代码能上传吗？</strong><br> A：查阅 Cursor 隐私与 <strong>Privacy Mode</strong> 说明；涉密项目用企业策略或本地模型方案。</p><h2 id="与其他工具的分工" tabindex="-1">与其他工具的分工 <a class="header-anchor" href="#与其他工具的分工" aria-label="Permalink to &quot;与其他工具的分工&quot;">​</a></h2><ul><li><strong>Cursor</strong>：日常编码主 IDE，可视化改多文件。</li><li><strong>Claude Code / Codex</strong>：终端 Agent、CI Headless、重度自动化。</li><li><strong>Copilot</strong>：在原生 VS Code 里轻量补全。</li></ul><hr><p><em>版本与定价以 Cursor 官网为准。</em></p>',30)])])}const m=r(d,[["render",l]]);export{C as __pageData,m as default};
